USE Olist_Ecommerce_Analytics;
GO


--Exercise 1 – Total Payment Value
--Business Question: What is the total payment value generated by Olist?

SELECT 
		SUM(payment_value) as Total_Payment_Value
FROM order_payments

--Exercise 2 : Payment Methods.
--Business Question: How many orders used each payment method?

SELECT 
		Payment_type , 
		COUNT(DISTINCT(order_id))as total_orders
FROM 
		dbo.order_payments
GROUP BY 
		Payment_type
ORDER BY total_orders DESC


--Exercise 3 – Payment Value by Method
--Business Question: How much total payment value was generated through each payment method?

SELECT 
		Payment_type , 
		SUM(payment_value) as total_payment_value
FROM 
		dbo.order_payments
GROUP BY 
		Payment_type
ORDER BY total_payment_value DESC


--Exercise 4 – Instalment Analysis
--Business Question: How do customers distribute their orders across different instalment counts?

SELECT
	payment_installments , COUNT(*) as orders
FROM
	dbo.order_payments
GROUP BY 
	payment_installments
ORDER BY orders DESC

--Analysis focused on credit card installments

SELECT
    payment_installments,
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(payment_value) AS total_payment_value
FROM dbo.order_payments
WHERE payment_type = 'credit_card'
GROUP BY payment_installments
ORDER BY total_orders DESC;

-- Exercise 5: Average Payment Value
-- Business Question: What is the average payment value across all payment records?

SELECT
    AVG(payment_value) AS avg_payment_value
FROM dbo.order_payments;

--Average Payment per Order

SELECT
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(payment_value) AS total_payment_value,
    SUM(payment_value) / COUNT(DISTINCT order_id) AS average_payment_per_order
FROM dbo.order_payments;

--Exercise 6 – Monthly Payment Trends
--Business Question: How does the total payment value change month by month?

WITH montly_payments AS
(
    SELECT
        YEAR(o.order_purchase_timestamp) AS years,
        MONTH(o.order_purchase_timestamp) AS months,
        SUM(p.payment_value) AS monthly_payment
    FROM dbo.order_payments AS p
    INNER JOIN dbo.orders AS o
        ON p.order_id = o.order_id
    GROUP BY
        YEAR(o.order_purchase_timestamp),
        MONTH(o.order_purchase_timestamp)
),
previous_payments AS
(
    SELECT
        years,
        months,
        monthly_payment,
        LAG(monthly_payment) OVER (ORDER BY years, months) AS previous_mon
    FROM montly_payments
)
SELECT
    years,
    months,
    monthly_payment,
    previous_mon,
    ROUND(
        (monthly_payment - previous_mon) * 100.0
        / NULLIF(previous_mon, 0),
        2
    ) AS monthly_diff
FROM previous_payments
ORDER BY years, months;

--Exercise 7 – Payment Method Contribution %
--Business Question: What percentage of the total payment value comes from each payment method?

SELECT *
FROM dbo.order_payments

WITH payments_overall as (
SELECT 
	payment_type ,
	 SUM(payment_value) as payment_received
FROM dbo.order_payments
WHERE payment_type != 'not_defined'
GROUP BY 
	payment_type )
SELECT * ,
		SUM(payment_received) over () as total_received , 
		(payment_received * 1.0  / SUM(payment_received) over () ) * 100.0 as contribution
FROM payments_overall

--Exercise 8 – Payment Behaviour Analysis
--Business Question: How do customers distribute their payments across instalment counts, and what is the average payment value for each instalment group?

SELECT
		payment_installments , 
		COUNT(DISTINCT order_id) AS total_orders,
		SUM(payment_value) AS total_payment_value,
		AVG(payment_value) as avg_payment
FROM dbo.order_payments
GROUP BY
		payment_installments
ORDER BY payment_installments